package org.apache.parquet.crypto;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.lang.reflect.Field;
import java.util.Arrays;
import org.apache.parquet.crypto.DecryptionKeyRetriever;
import org.apache.parquet.crypto.FileDecryptionProperties;
import org.apache.parquet.format.AesGcmV1;
import org.apache.parquet.format.EncryptionAlgorithm;

public class InternalFileDecryptorSetFileCryptoMetaDataTests {

  @Test
  void initializesFileAadWithFilePrefixAndUniqueComponent() throws Exception {
    byte[] prefix = new byte[] {1, 2, 3};
    byte[] fileUnique = new byte[] {4, 5, 6};
    EncryptionAlgorithm algorithm = aesGcmAlgorithm(prefix, fileUnique, false);

    InternalFileDecryptor decryptor = newDecryptorWithExplicitFooterKey(prefix);
    decryptor.setFileCryptoMetaData(algorithm, false, null);

    assertArrayEquals(
        new byte[] {1, 2, 3, 4, 5, 6},
        fieldValue(decryptor, "fileAAD", byte[].class));
    assertSame(algorithm, fieldValue(decryptor, "algorithm", EncryptionAlgorithm.class));
    assertFalse(fieldValue(decryptor, "encryptedFooter", Boolean.class));
  }

  @Test
  void initializesFileAadWithUniqueComponentWhenNoPrefixIsUsed() throws Exception {
    byte[] fileUnique = new byte[] {9, 8, 7};
    EncryptionAlgorithm algorithm = aesGcmAlgorithm(null, fileUnique, false);

    InternalFileDecryptor decryptor = newDecryptorWithExplicitFooterKey(null);
    decryptor.setFileCryptoMetaData(algorithm, false, null);

    assertArrayEquals(
        fileUnique,
        fieldValue(decryptor, "fileAAD", byte[].class));
  }

  @Test
  void obtainsFooterKeyFromRetrieverWhenFooterKeyWasNotSupplied() throws Exception {
    byte[] metadata = new byte[] {10, 11};
    byte[] retrievedKey = new byte[16];

    DecryptionKeyRetriever retriever = keyMetadata -> {
      assertArrayEquals(metadata, keyMetadata);
      return retrievedKey;
    };

    FileDecryptionProperties properties = FileDecryptionProperties.builder()
        .withKeyRetriever(retriever)
        .withoutFooterSignatureVerification()
        .build();
    InternalFileDecryptor decryptor = new InternalFileDecryptor(properties);

    decryptor.setFileCryptoMetaData(
        aesGcmAlgorithm(null, new byte[] {12}, false), true, metadata);

    assertSame(retrievedKey, fieldValue(decryptor, "footerKey", byte[].class));
  }

  @Test
  void acceptsReuseWithIdenticalMetadata() {
    EncryptionAlgorithm algorithm = aesGcmAlgorithm(null, new byte[] {1, 2}, false);
    byte[] metadata = new byte[] {3, 4};

    InternalFileDecryptor decryptor = newDecryptorWithExplicitFooterKey(null);
    decryptor.setFileCryptoMetaData(algorithm, false, metadata);
    decryptor.setFileCryptoMetaData(algorithm, false, Arrays.copyOf(metadata, metadata.length));

    assertDoesNotThrow(() -> decryptor.setFileCryptoMetaData(algorithm, false, metadata));
  }

  @Test
  void rejectsReuseWithDifferentFooterEncryptionFlag() {
    EncryptionAlgorithm algorithm = aesGcmAlgorithm(null, new byte[] {1}, false);
    InternalFileDecryptor decryptor = newDecryptorWithExplicitFooterKey(null);

    decryptor.setFileCryptoMetaData(algorithm, false, null);

    ParquetCryptoRuntimeException exception = assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, true, null));

    assertEquals("Decryptor re-use: Different footer encryption", exception.getMessage());
  }

  @Test
  void rejectsMissingRequiredExternalPrefix() {
    EncryptionAlgorithm algorithm = aesGcmAlgorithm(null, new byte[] {1, 2}, true);
    InternalFileDecryptor decryptor = newDecryptorWithExplicitFooterKey(null);

    ParquetCryptoRuntimeException exception = assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, false, null));

    assertTrue(exception.getMessage().contains("AAD prefix"));
  }

  @Test
  void rejectsPrefixThatDiffersFromPrefixStoredInFile() {
    byte[] filePrefix = new byte[] {1, 2};
    byte[] propertyPrefix = new byte[] {3, 4};
    EncryptionAlgorithm algorithm = aesGcmAlgorithm(filePrefix, new byte[] {5}, false);

    InternalFileDecryptor decryptor = newDecryptorWithExplicitFooterKey(propertyPrefix);

    ParquetCryptoRuntimeException exception = assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, false, null));

    assertEquals(
        "AAD Prefix in file and in decryption properties is not the same",
        exception.getMessage());
  }

  @Test
  void rejectsUnsupportedAlgorithm() {
    EncryptionAlgorithm unsupported = new EncryptionAlgorithm();
    InternalFileDecryptor decryptor = newDecryptorWithExplicitFooterKey(null);

    ParquetCryptoRuntimeException exception = assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(unsupported, false, null));

    assertTrue(exception.getMessage().startsWith("Unsupported algorithm:"));
  }

  private static EncryptionAlgorithm aesGcmAlgorithm(
      byte[] aadPrefix, byte[] fileUnique, boolean supplyPrefix) {
    AesGcmV1 aesGcm = new AesGcmV1();
    aesGcm.setAad_file_unique(fileUnique);
    aesGcm.setSupply_aad_prefix(supplyPrefix);
    if (aadPrefix != null) {
      aesGcm.setAad_prefix(aadPrefix);
    }

    EncryptionAlgorithm algorithm = new EncryptionAlgorithm();
    algorithm.setAES_GCM_V1(aesGcm);
    return algorithm;
  }

  private static InternalFileDecryptor newDecryptorWithExplicitFooterKey(byte[] aadPrefix) {
    FileDecryptionProperties.Builder builder = FileDecryptionProperties.builder()
        .withFooterKey(new byte[16])
        .withoutFooterSignatureVerification();
    if (aadPrefix != null) {
      builder.withAADPrefix(aadPrefix);
    }
    return new InternalFileDecryptor(builder.build());
  }

  @SuppressWarnings("unchecked")
  private static <T> T fieldValue(
      InternalFileDecryptor decryptor, String fieldName, Class<T> fieldType) throws Exception {
    Field field = InternalFileDecryptor.class.getDeclaredField(fieldName);
    field.setAccessible(true);
    return (T) field.get(decryptor);
  }
}

package org.apache.parquet.crypto;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import org.apache.parquet.crypto.FileDecryptionProperties;
import org.apache.parquet.crypto.DecryptionKeyRetriever;
import org.apache.parquet.crypto.ParquetCryptoRuntimeException;
import org.apache.parquet.format.EncryptionAlgorithm;
import org.apache.parquet.format.AesGcmV1;
import org.apache.parquet.format.AesGcmCtrV1;
import java.util.Arrays;

public class InternalFileDecryptorSetFileCryptoMetaDataTests {

    @Test
    public void testSetFileCryptoMetaDataWithValidAesGcmV1() {
        byte[] footerKeyMetaData = new byte[]{1, 2, 3};
        byte[] expectedFooterKey = new byte[]{4, 5, 6};

        DecryptionKeyRetriever keyRetriever = metadata -> {
            if (Arrays.equals(metadata, footerKeyMetaData)) {
                return expectedFooterKey;
            }
            return null;
        };

        FileDecryptionProperties properties = FileDecryptionProperties.builder()
                .withKeyRetriever(keyRetriever)
                .withoutFooterSignatureVerification()
                .build();

        InternalFileDecryptor decryptor = new InternalFileDecryptor(properties);
        EncryptionAlgorithm algorithm = EncryptionAlgorithm.AES_GCM_V1(new AesGcmV1());

        assertDoesNotThrow(() -> decryptor.setFileCryptoMetaData(algorithm, true, footerKeyMetaData));
        assertNotNull(decryptor.fetchFooterDecryptor(), "Footer decryptor should be initialized");
    }

    @Test
    public void testSetFileCryptoMetaDataWithUnsupportedAlgorithm() {
        DecryptionKeyRetriever keyRetriever = metadata -> null;

        FileDecryptionProperties properties = FileDecryptionProperties.builder()
                .withKeyRetriever(keyRetriever)
                .withoutFooterSignatureVerification()
                .build();

        InternalFileDecryptor decryptor = new InternalFileDecryptor(properties);
        EncryptionAlgorithm unsupportedAlgorithm = new EncryptionAlgorithm(); 

        ParquetCryptoRuntimeException exception = assertThrows(ParquetCryptoRuntimeException.class, 
                () -> decryptor.setFileCryptoMetaData(unsupportedAlgorithm, false, null));
        assertTrue(exception.getMessage().startsWith("Unsupported algorithm: "), 
                "Exception message should start with 'Unsupported algorithm: ' but was: " + exception.getMessage());
    }

    @Test
    public void testSetFileCryptoMetaDataWithMismatchedAadPrefix() {
        byte[] aadPrefixInProperties = new byte[]{1, 2, 3};
        byte[] aadPrefixInFile = new byte[]{4, 5, 6};
        byte[] footerKeyMetaData = new byte[]{7, 8, 9};
        byte[] expectedFooterKey = new byte[]{10, 11, 12};

        DecryptionKeyRetriever keyRetriever = metadata -> expectedFooterKey;

        AesGcmV1 aesGcmV1 = new AesGcmV1();
